# Test more edge cases for sieve and factor
import sys
sys.path.insert(0, '.')
from more_itertools.recipes import sieve, factor

# More edge cases for sieve
print("=== sieve edge cases ===")
for n in [-1, -5, 0, 1, 2, 3, 4, 5, 10, 100]:
    try:
        result = list(sieve(n))
        print(f"sieve({n}) = {result}")
    except Exception as e:
        print(f"sieve({n}) raised {type(e).__name__}: {e}")

print()
